import type { Vec3 } from '../contracts/math';
import { addVec3, cloneVec3, normalizeVec3, scaleVec3 } from './vec';

/** Kinematic obstacles driven purely by the hole clock. */
export type MoverKind = 'platform' | 'sliding-wall' | 'door';

/** What happens once the mover reaches the far end of its travel. */
export type MoverLoop = 'ping-pong' | 'loop' | 'once';

export interface MoverConfig {
  id: string;
  kind: MoverKind;
  origin: Vec3;
  axis: Vec3;
  distance: number;
  speed: number;
  phase?: number;
  loop?: MoverLoop;
  pauseSeconds?: number;
  enabled?: boolean;
}

export interface MoverSample {
  position: Vec3;
  velocity: Vec3;
  progress: number;
}

interface MoverTrack {
  direction: Vec3;
  travel: number;
  pause: number;
}

interface MoverPhase {
  progress: number;
  sign: number;
}

function zeroVec(): Vec3 {
  return { x: 0, y: 0, z: 0 };
}

function staticSample(config: MoverConfig): MoverSample {
  return { position: cloneVec3(config.origin), velocity: zeroVec(), progress: 0 };
}

/** Returns null when the mover cannot move at all and has to be treated as static. */
function resolveTrack(config: MoverConfig): MoverTrack | null {
  if (config.enabled === false) return null;
  if (!Number.isFinite(config.distance) || !Number.isFinite(config.speed)) return null;
  if (config.distance <= 0 || config.speed <= 0) return null;
  const direction = normalizeVec3(config.axis);
  if (!direction) return null;
  const rawPause = config.pauseSeconds ?? 0;
  const pause = Number.isFinite(rawPause) && rawPause > 0 ? rawPause : 0;
  return { direction, travel: config.distance / config.speed, pause };
}

function wrap(value: number, period: number): number {
  return ((value % period) + period) % period;
}

/**
 * Maps mover time to a 0..1 position along the axis plus the sign of the motion.
 * A sign of 0 means the mover is parked at one of the ends.
 */
function resolvePhase(loop: MoverLoop, time: number, travel: number, pause: number): MoverPhase {
  if (loop === 'once') {
    if (time <= 0) return { progress: 0, sign: 0 };
    if (time >= travel) return { progress: 1, sign: 0 };
    return { progress: time / travel, sign: 1 };
  }

  if (loop === 'loop') {
    const local = wrap(time, travel + pause);
    if (local < travel) return { progress: local / travel, sign: 1 };
    return { progress: 1, sign: 0 };
  }

  let local = wrap(time, 2 * travel + 2 * pause);
  if (local < travel) return { progress: local / travel, sign: 1 };
  local -= travel;
  if (local < pause) return { progress: 1, sign: 0 };
  local -= pause;
  if (local < travel) return { progress: 1 - local / travel, sign: -1 };
  return { progress: 0, sign: 0 };
}

/**
 * Samples the mover at `elapsed` seconds of hole time. The result depends only on
 * the clock, so every client driving the same config stays in sync without state.
 */
export function sampleMover(config: MoverConfig, elapsed: number): MoverSample {
  const track = resolveTrack(config);
  if (!track) return staticSample(config);

  const phase = config.phase ?? 0;
  if (!Number.isFinite(elapsed) || !Number.isFinite(phase)) return staticSample(config);

  const step = resolvePhase(config.loop ?? 'ping-pong', elapsed + phase, track.travel, track.pause);
  return {
    position: addVec3(config.origin, scaleVec3(track.direction, config.distance * step.progress)),
    velocity: step.sign === 0 ? zeroVec() : scaleVec3(track.direction, step.sign * config.speed),
    progress: step.progress,
  };
}

/** Velocity a ball inherits from the mover while it rides on it. */
export function carryVelocity(config: MoverConfig, elapsed: number, contact: boolean): Vec3 {
  if (!contact) return zeroVec();
  return sampleMover(config, elapsed).velocity;
}
