import { describe, it, expect } from 'vitest';
import { carryVelocity, sampleMover } from './movers';
import type { MoverConfig } from './movers';
import { vec3 } from './vec';

// distance 4 at speed 2 means a 2 second one way travel.
function base(overrides: Partial<MoverConfig> = {}): MoverConfig {
  return {
    id: 'mover-1',
    kind: 'platform',
    origin: vec3(0, 1, 0),
    axis: vec3(1, 0, 0),
    distance: 4,
    speed: 2,
    ...overrides,
  };
}

describe('sampleMover', () => {
  it('ping-pong reverses direction after the far end', () => {
    const config = base();

    const forward = sampleMover(config, 1);
    expect(forward.progress).toBeCloseTo(0.5);
    expect(forward.position.x).toBeCloseTo(2);
    expect(forward.position.y).toBeCloseTo(1);
    expect(forward.velocity.x).toBeCloseTo(2);

    const backward = sampleMover(config, 3);
    expect(backward.progress).toBeCloseTo(0.5);
    expect(backward.position.x).toBeCloseTo(2);
    expect(backward.velocity.x).toBeCloseTo(-2);

    const restarted = sampleMover(config, 4);
    expect(restarted.progress).toBeCloseTo(0);
    expect(restarted.velocity.x).toBeCloseTo(2);
  });

  it('loop wraps back to the start instead of reversing', () => {
    const config = base({ loop: 'loop' });

    expect(sampleMover(config, 1.5).progress).toBeCloseTo(0.75);

    const wrapped = sampleMover(config, 2.5);
    expect(wrapped.progress).toBeCloseTo(0.25);
    expect(wrapped.position.x).toBeCloseTo(1);
    expect(wrapped.velocity.x).toBeCloseTo(2);
  });

  it('once clamps at the far end and ends with zero velocity', () => {
    const config = base({ loop: 'once', kind: 'door' });

    expect(sampleMover(config, 1).velocity.x).toBeCloseTo(2);

    const done = sampleMover(config, 9);
    expect(done.progress).toBe(1);
    expect(done.position.x).toBeCloseTo(4);
    expect(done.velocity).toEqual(vec3(0, 0, 0));
  });

  it('pause freezes velocity at each end', () => {
    const config = base({ pauseSeconds: 1 });

    const paused = sampleMover(config, 2.5);
    expect(paused.progress).toBeCloseTo(1);
    expect(paused.position.x).toBeCloseTo(4);
    expect(paused.velocity).toEqual(vec3(0, 0, 0));

    const returning = sampleMover(config, 3.5);
    expect(returning.progress).toBeCloseTo(0.75);
    expect(returning.velocity.x).toBeCloseTo(-2);

    const parked = sampleMover(config, 5.5);
    expect(parked.progress).toBeCloseTo(0);
    expect(parked.position.x).toBeCloseTo(0);
    expect(parked.velocity).toEqual(vec3(0, 0, 0));
  });

  it('phase offsets the timeline', () => {
    const phased = sampleMover(base({ phase: 1 }), 0);
    const plain = sampleMover(base(), 1);

    expect(phased.position).toEqual(plain.position);
    expect(phased.velocity).toEqual(plain.velocity);
    expect(phased.progress).toBeCloseTo(plain.progress);
  });

  it('treats degenerate or disabled configs as static', () => {
    const degenerate = [
      base({ speed: 0 }),
      base({ distance: 0 }),
      base({ axis: vec3(0, 0, 0) }),
      base({ speed: Number.NaN }),
      base({ enabled: false }),
    ];

    for (const config of degenerate) {
      const sample = sampleMover(config, 1.25);
      expect(sample.position).toEqual(vec3(0, 1, 0));
      expect(sample.velocity).toEqual(vec3(0, 0, 0));
      expect(sample.progress).toBe(0);
    }

    expect(sampleMover(base(), Number.NaN).progress).toBe(0);
  });

  it('normalizes the axis so distance drives the travel length', () => {
    const sample = sampleMover(base({ axis: vec3(0, 0, 3), loop: 'once' }), 9);
    expect(sample.position).toEqual(vec3(0, 1, 4));
  });
});

describe('carryVelocity', () => {
  it('returns the mover velocity only while in contact', () => {
    const config = base({ kind: 'sliding-wall' });

    expect(carryVelocity(config, 1, true).x).toBeCloseTo(2);
    expect(carryVelocity(config, 1, false)).toEqual(vec3(0, 0, 0));
    expect(carryVelocity(base({ loop: 'once' }), 9, true)).toEqual(vec3(0, 0, 0));
  });
});
